// The TanStack Query client: the cache of server data for the whole app. Data counts as fresh for
// 30 seconds (no refetch when another component asks), refetches when you come back to the tab,
// and a failed request is retried once, unless the server said 4xx, which a retry won't fix.
import { QueryClient } from "@tanstack/react-query";
import { ApiError } from "@/lib/api-client";

const isClientError = (error: unknown) => error instanceof ApiError && error.status >= 400 && error.status < 500;

/** Tests pass retry: false, so a failing request fails at once instead of after a retry delay. */
export function createQueryClient({ retry = true }: { retry?: boolean } = {}): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 30_000,
        refetchOnWindowFocus: true,
        retry: retry ? (failureCount, error) => failureCount < 1 && !isClientError(error) : false,
      },
    },
  });
}

export const queryClient = createQueryClient();

export function ProjectCard({ project }: { project: ProjectSummary }) {
  const queryClient = useQueryClient();
  const headingId = `project-${project.id}-name`;

  function prefetchBoard() {
    void queryClient.prefetchQuery(taskQueries.list(project.id, boardParams(DEFAULT_FILTERS)));
  }

  return (
    <article className={styles.card} aria-labelledby={headingId} style={{ "--project-color": project.color } as CSSProperties} onMouseEnter={prefetchBoard}>
      <h2 id={headingId} className={styles.name}>
        <Link to={`/projects/${project.id}`} onFocus={prefetchBoard}>
          {project.name}
        </Link>
      </h2>
      {/* ... */}
    </article>
  );
}

// Every TanStack Query cache key in one place. A key holds everything its request depends on, and
// keys nest, so invalidating ["projects", 1, "tasks"] refreshes every task list of project 1,
// whatever its filters. Features build their queries from these, and a feature that changes
// another feature's data (a label on a task) finds the keys to update here.
import type { TaskListParams } from "@/features/tasks/types";

export const queryKeys = {
  me: () => ["me"] as const,
  users: (q: string) => ["users", { q }] as const,
  projects: () => ["projects"] as const,
  project: (projectId: number) => ["projects", projectId] as const,
  projectStats: (projectId: number) => ["projects", projectId, "stats"] as const,
  projectLabels: (projectId: number) => ["projects", projectId, "labels"] as const,
  projectTasks: (projectId: number) => ["projects", projectId, "tasks"] as const,
  taskList: (projectId: number, params: TaskListParams) => ["projects", projectId, "tasks", params] as const,
  task: (taskId: number) => ["tasks", taskId] as const,
  comments: (taskId: number) => ["tasks", taskId, "comments"] as const,
  watchers: (taskId: number) => ["tasks", taskId, "watchers"] as const,
};

export function useRenameProject(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (name: string) => renameProject(projectId, name),
    onSuccess: (project) => {
      queryClient.setQueryData(queryKeys.project(projectId), project);
      return queryClient.invalidateQueries({ queryKey: queryKeys.projects(), exact: true });
    },
  });
}

export function useTransitionTask() {
  const queryClient = useQueryClient();
  const toast = useToast();

  return useMutation({
    mutationFn: ({ task, to }: { task: Task; to: TaskStatus }) => transitionTask(task.id, to),
    onMutate: async ({ task, to }) => {
      const snapshot = await snapshotTask(queryClient, task);
      writeTask(queryClient, task, (current) => ({ ...current, status: to }));
      return snapshot;
    },
    onError: (_error, _variables, snapshot) => {
      if (snapshot) restoreTask(queryClient, snapshot);
      toast("Couldn't move the task. It's back where it was.", "danger");
    },
    onSuccess: (saved) => writeTask(queryClient, saved, () => saved),
    onSettled: (_data, _error, { task }) => refreshProject(queryClient, task.project_id),
  });
}
